CREATE TABLE IF NOT EXISTS students ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, student_id TEXT, name TEXT, first_name TEXT, last_name TEXT, program TEXT, department TEXT, semester INTEGER, section TEXT, batch TEXT, admission_year INTEGER, date_of_birth TEXT, gender TEXT, phone TEXT, email TEXT, guardian_name TEXT, guardian_phone TEXT, address TEXT, category TEXT, blood_group TEXT, status TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_students_institution ON students(institution_id);
CREATE TABLE IF NOT EXISTS faculty ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, faculty_id TEXT, name TEXT, designation TEXT, department TEXT, qualification TEXT, specialization TEXT, email TEXT, phone TEXT, joining_date TEXT, experience_years REAL, is_hod INTEGER, status TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_faculty_institution ON faculty(institution_id);
CREATE TABLE IF NOT EXISTS staff ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, staff_id TEXT, name TEXT, designation TEXT, department TEXT, email TEXT, phone TEXT, joining_date TEXT, status TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_staff_institution ON staff(institution_id);
CREATE TABLE IF NOT EXISTS programs ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, code TEXT, name TEXT, department TEXT, level TEXT, duration_semesters INTEGER, intake INTEGER, status TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_programs_institution ON programs(institution_id);
CREATE TABLE IF NOT EXISTS departments ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, code TEXT, name TEXT, hod_id TEXT, hod_name TEXT, hod_email TEXT, status TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_departments_institution ON departments(institution_id);
CREATE TABLE IF NOT EXISTS courses ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, code TEXT, name TEXT, program TEXT, department TEXT, semester INTEGER, credits REAL, faculty_id TEXT, course_type TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_courses_institution ON courses(institution_id);
CREATE TABLE IF NOT EXISTS attendance ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, student_id TEXT, student_name TEXT, program TEXT, department TEXT, semester INTEGER, section TEXT, course_code TEXT, period TEXT, classes_held INTEGER, classes_attended INTEGER, classes_absent INTEGER, attendance_percent REAL, recorded_on TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_attendance_institution ON attendance(institution_id);
CREATE TABLE IF NOT EXISTS fees ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, student_id TEXT, student_name TEXT, program TEXT, semester INTEGER, academic_year TEXT, fee_type TEXT, amount_due REAL, amount_paid REAL, balance REAL, due_date TEXT, paid_on TEXT, receipt_no TEXT, payment_mode TEXT, status TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_fees_institution ON fees(institution_id);
CREATE TABLE IF NOT EXISTS exams ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, student_id TEXT, student_name TEXT, program TEXT, semester INTEGER, course_code TEXT, course_name TEXT, exam_name TEXT, marks_obtained REAL, max_marks REAL, grade TEXT, result_status TEXT, exam_date TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_exams_institution ON exams(institution_id);
CREATE TABLE IF NOT EXISTS enrollments ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, student_id TEXT, program TEXT, semester INTEGER, academic_year TEXT, section TEXT, status TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_enrollments_institution ON enrollments(institution_id);
CREATE TABLE IF NOT EXISTS admissions ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, application_id TEXT, name TEXT, program TEXT, status TEXT, applied_on TEXT, phone TEXT, email TEXT, category TEXT, entrance_score REAL, academic_year TEXT, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_admissions_institution ON admissions(institution_id);
CREATE TABLE IF NOT EXISTS events ( row_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, record_key TEXT NOT NULL, title TEXT, event_date TEXT, end_date TEXT, category TEXT, organizer TEXT, venue TEXT, description TEXT, participants INTEGER, attributes_json TEXT NOT NULL DEFAULT '{}', normalizations_json TEXT NOT NULL DEFAULT '[]', issues_json TEXT NOT NULL DEFAULT '[]', content_hash TEXT NOT NULL, source_file_id TEXT, source_file_name TEXT, source_locator TEXT, ingestion_job_id TEXT, imported_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(institution_id, record_key) );
CREATE INDEX IF NOT EXISTS idx_events_institution ON events(institution_id);
CREATE TABLE IF NOT EXISTS ingestion_files ( file_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, file_name TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, object_key TEXT NOT NULL, file_kind TEXT NOT NULL DEFAULT 'unknown', uploaded_by TEXT NOT NULL, uploaded_at TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS idx_ingestion_files_institution ON ingestion_files(institution_id, uploaded_at);
CREATE TABLE IF NOT EXISTS ingestion_jobs ( job_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, file_id TEXT, entity TEXT, status TEXT NOT NULL, stage TEXT NOT NULL, source_kind TEXT NOT NULL DEFAULT 'upload', requested_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, mapping_json TEXT NOT NULL DEFAULT '{}', report_json TEXT NOT NULL DEFAULT '{}', options_json TEXT NOT NULL DEFAULT '{}', error TEXT, row_count INTEGER NOT NULL DEFAULT 0, sheet_name TEXT );
CREATE INDEX IF NOT EXISTS idx_ingestion_jobs_institution ON ingestion_jobs(institution_id, created_at);
CREATE TABLE IF NOT EXISTS ingestion_records ( record_id TEXT PRIMARY KEY, job_id TEXT NOT NULL, institution_id TEXT NOT NULL, row_number INTEGER NOT NULL, locator TEXT NOT NULL, raw_json TEXT NOT NULL, normalized_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL, action TEXT NOT NULL DEFAULT 'pending', record_key TEXT, issues_json TEXT NOT NULL DEFAULT '[]' );
CREATE INDEX IF NOT EXISTS idx_ingestion_records_job ON ingestion_records(job_id, row_number);
CREATE TABLE IF NOT EXISTS review_items ( review_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, job_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, resolved_at TEXT, resolved_by TEXT, resolution_json TEXT NOT NULL DEFAULT '{}' );
CREATE INDEX IF NOT EXISTS idx_review_items_job ON review_items(institution_id, job_id, status);
CREATE TABLE IF NOT EXISTS mapping_profiles ( profile_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, entity TEXT NOT NULL, header_signature TEXT NOT NULL, mapping_json TEXT NOT NULL, approved_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(institution_id, entity, header_signature) );
CREATE TABLE IF NOT EXISTS documents ( document_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, title TEXT NOT NULL, file_name TEXT NOT NULL, object_key TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, classification TEXT NOT NULL DEFAULT 'internal', category TEXT NOT NULL DEFAULT 'general', uploaded_by TEXT NOT NULL, uploaded_at TEXT NOT NULL, page_count INTEGER NOT NULL DEFAULT 0, chunk_count INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'indexed' );
CREATE INDEX IF NOT EXISTS idx_documents_institution ON documents(institution_id, uploaded_at);
CREATE TABLE IF NOT EXISTS document_chunks ( chunk_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, document_id TEXT NOT NULL, chunk_index INTEGER NOT NULL, page_number INTEGER, text TEXT NOT NULL, embedding_json TEXT NOT NULL, token_count INTEGER NOT NULL DEFAULT 0 );
CREATE INDEX IF NOT EXISTS idx_document_chunks_document ON document_chunks(institution_id, document_id, chunk_index);
CREATE TABLE IF NOT EXISTS generated_reports ( report_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, title TEXT NOT NULL, format TEXT NOT NULL, object_key TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, row_count INTEGER NOT NULL DEFAULT 0, tool_name TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS idx_generated_reports_institution ON generated_reports(institution_id, created_at);
CREATE TABLE IF NOT EXISTS notifications ( notification_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, recipient_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, channel TEXT NOT NULL DEFAULT 'in_app', status TEXT NOT NULL DEFAULT 'unread', reference_type TEXT, reference_id TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, read_at TEXT );
CREATE INDEX IF NOT EXISTS idx_notifications_recipient ON notifications(institution_id, recipient_id, created_at);
CREATE TABLE IF NOT EXISTS email_outbox ( email_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, recipients_json TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, attachments_json TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL, provider TEXT NOT NULL, provider_message_id TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, sent_at TEXT, error TEXT );
CREATE INDEX IF NOT EXISTS idx_email_outbox_institution ON email_outbox(institution_id, created_at);
CREATE TABLE IF NOT EXISTS agent_runs ( run_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, principal_id TEXT NOT NULL, request_id TEXT NOT NULL, channel TEXT NOT NULL, command_sha256 TEXT NOT NULL, status TEXT NOT NULL, plan_json TEXT NOT NULL DEFAULT '[]', steps_json TEXT NOT NULL DEFAULT '[]', tool_names_json TEXT NOT NULL DEFAULT '[]', duration_ms INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS idx_agent_runs_institution ON agent_runs(institution_id, created_at);
CREATE TABLE IF NOT EXISTS approvals ( approval_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, principal_id TEXT NOT NULL, tool_name TEXT NOT NULL, arguments_json TEXT NOT NULL, arguments_sha256 TEXT NOT NULL, status TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, expires_at TEXT NOT NULL, decided_at TEXT, decided_by TEXT );
CREATE INDEX IF NOT EXISTS idx_approvals_institution ON approvals(institution_id, status, created_at);
CREATE TABLE IF NOT EXISTS background_jobs ( job_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, job_type TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, started_at TEXT, finished_at TEXT, result_json TEXT NOT NULL DEFAULT '{}', error TEXT );
CREATE INDEX IF NOT EXISTS idx_background_jobs_status ON background_jobs(status, created_at);
